"""tables.md from design.json, table.json, probes.json, swaps.json, prefix.json, posthoc_histories.json (bump policy).

    .venv/bin/python studies/8_language_models/bump_policy/tables.py
"""

from __future__ import annotations

import json
from pathlib import Path

import numpy as np

HERE = Path(__file__).resolve().parent
ci = lambda x: f"{x[0]:.2f}–{x[1]:.2f}"
ld = lambda name: json.loads((HERE / name).read_text()) if (HERE / name).exists() else None


def main():
    d = ld("design.json"); T = ld("table.json"); P = ld("probes.json"); C = ld("swaps.json"); D = ld("prefix.json"); H = ld("posthoc_histories.json")
    L = ["# Bump policy: tables", "", f"Generated by `tables.py`. {d['n_sets']} reachable belief sets; the optimum's episodes visit {d['coverage']['optimum_4096_episodes']}, the 100k training data {d['coverage']['train_100000']}, the 10k data {d['coverage']['train_10000']}. The optimal action is linear in membership at {d['readout_ceiling']['uniform over sets']['linear']:.3f} over all sets ({d['readout_ceiling']['optimum frequency']['linear']:.3f} on the optimum's distribution); readouts fitted on the training-visited sets transfer to never-visited ones at {d['readout_ceiling']['transfer']['linear']['unseen']:.3f} (linear) / {d['readout_ceiling']['transfer']['mlp256']['unseen']:.3f} (MLP).", ""]
    if T:
        L += ["## A. The policy on every reachable set (the shortest history to each)", "", "| model | all sets: optimal | regret | optimum-visited: optimal (n) | training-visited, not by the optimum (n) | never visited (n) | never visited: agreement with the linear / MLP transfer readout (their optimality) |", "|---|---|---|---|---|---|---|"]
        for name, m in T["models"].items():
            g = list(m["table"].items()); tr = m["transfer"]["readouts"]
            L.append(f"| {name} | {m['all']['optimal']:.3f} | {m['all']['regret']:.3f} | " + " | ".join(f"{v['optimal']:.3f} ({ci(v['optimal_ci'])}; {v['n']})" for _, v in g) + f" | {tr['linear']['model_agrees_unseen']:.3f} / {tr['mlp256']['model_agrees_unseen']:.3f} ({tr['linear']['readout_optimal_unseen']:.3f} / {tr['mlp256']['readout_optimal_unseen']:.3f}) |")
        L += ["", "By set size (optimal share, sets 1 / 2–4 / 5–16 / > 16), and at near-ties (margin < 0.01) against clear decisions:", "", "| model | group | by size | near-tie / clear |", "|---|---|---|---|"]
        for name, m in T["models"].items():
            for g, v in m["table"].items(): L.append(f"| {name} | {g} | " + " / ".join(f"{v['by_size'][b]:.2f}" if v["by_size"][b] is not None else "–" for b in ("1", "2-4", "5-16", ">16")) + f" | {v['near_tie']:.2f} / {v['clear']:.2f} |")
        L += ["", "## A1. Set-sufficiency: the same action on every history of a set", "", f"Histories per set (the shortest plus up to three from random-action and ε = 0.5 episodes): " + ", ".join(f"{k}: {v}" for k, v in T["histories_per_set"].items()) + ".", "",
              "| model | all sets with ≥ 2 histories: same action (95 % CI) | baseline: two different sets of the same size | between-set share of the logits' variance | optimum-visited | training-visited, not by the optimum | never visited |", "|---|---|---|---|---|---|---|"]
        for name, m in T["models"].items():
            s = m["sufficiency"]; g = [v for k, v in s.items() if k != "all"]
            L.append(f"| {name} | {s['all']['same']:.3f} ({ci(s['all']['same_ci'])}; {s['all']['n']}) | {s['all']['baseline_same_size']:.3f} | {s['all']['between_set_variance_share']:.3f} | " + " | ".join(f"{v['same']:.3f} ({v['n']})" if v["same"] is not None else "–" for v in g) + " |")
        L += ["", "## A3. The exact value of the table as a policy over the belief MDP", "", "| model | table | V^π(start) / V*(start) | mean V^π / V* over all sets (95 % CI) | over never-visited sets | sets from which V^π < 0.5 V* | by size |", "|---|---|---|---|---|---|---|"]
        for name, m in T["models"].items():
            for lab in ("shortest", "majority"):
                v = m[f"value_{lab}"]; L.append(f"| {name} | {lab} history's action | {v['start']:.4f} / {v['start_optimal']:.4f} = {v['start_ratio']:.3f} | {v['mean_ratio_all']:.3f} ({ci(v['mean_ratio_ci'])}) | {v['mean_ratio_unseen']:.3f} | {v['lost']:.3f} | " + " / ".join(f"{v['by_size'][b]:.2f}" for b in ("1", "2-4", "5-16", ">16")) + " |")
        L.append("")
    if H:
        L += ["## Post hoc: the same training-visited sets reached by three kinds of history (`posthoc_histories.json`)", "", f"{H['n_sets']} training-visited sets; the 100k model.", "", "| history | optimal (95 % CI) | optimum-visited sets | training-visited, not by the optimum | mean length |", "|---|---|---|---|---|"]
        for k, v in H["kinds"].items(): g = list(v["by_group"].values()); L.append(f"| {k} | {v['optimal']:.3f} ({ci(v['optimal_ci'])}) | {g[0]:.3f} | {g[1]:.3f} | {v['mean_length']:.1f} |")
        L += ["", "Agreement of the model's action between kinds: " + "; ".join(f"{k} {v:.3f}" for k, v in H["agreement"].items()) + ".", "Training-data history against the shortest, disagreement by their difference in length: " + "; ".join(f"{k}: {v['disagree']:.3f} ({v['n']})" for k, v in H["disagreement_by_length_difference"].items()) + f"; by the last action (same / different): {H['disagreement_by_last_action']['same']:.3f} / {H['disagreement_by_last_action']['different']:.3f}.",
              f"When they disagree ({H['when_disagreeing']['n']} sets): both optimal {H['when_disagreeing']['both_optimal']:.2f}, only the training history's {H['when_disagreeing']['only_training_optimal']:.2f}, only the shortest's {H['when_disagreeing']['only_shortest_optimal']:.2f}, neither {H['when_disagreeing']['neither']:.2f}.", ""]
    if P:
        L += [f"## B1. Linear probes by layer at the decision token ({P['model']}; {P['n']} decisions uniform over sets, shortest histories; held out by set)", "", "| layer | set: exact | Jaccard | Q*: R² | Q* argmax optimal | V*: R² | optimal action: in-set accuracy | P(bump): R² | cell marginal: R² | heading marginal: R² |", "|---|---|---|---|---|---|---|---|---|---|"]
        for r in P["layers"]: L.append(f"| {r['layer']} | {r['set_exact']:.3f} | {r['set_jaccard']:.2f} | {r['Q_r2']:.3f} | {r['Q_argmax_optimal']:.3f} | {r['V_r2']:.3f} | {r['action_optimal']:.3f} | {r['pbump_r2']:.3f} | {r['cell_r2']:.3f} | {r['heading_r2']:.3f} |")
        L += ["", "Best layers: " + ", ".join(f"{k} {v}" for k, v in P["best_layer"].items()) + f". The model's own decision is optimal on {P['model_optimal_on_these']:.3f} of these decisions (a probe for the optimal action is bounded by what the state holds, not by the model's behaviour).", ""]
        if "readout_form" in P:
            L += ["## B2. The model's logits as a function of the exact membership vector, all reachable sets (half fit, half test)", "", "| readout | R² | agreement with the model's decision (95 % CI) | optimal |", "|---|---|---|---|"]
            for k, v in P["readout_form"].items(): L.append(f"| {k} | {v['r2']:.3f} | {v['agreement']:.3f} ({ci(v['agreement_ci'])}) | {v['optimal']:.3f} |")
            L += [f"| the model itself | 1 | 1 | {P['model_optimal_all_sets']:.3f} |", f"| the optimum, linear in membership (design) | | | {d['readout_ceiling']['uniform over sets']['linear']:.3f} |", ""]
        if "step_tokens" in P:
            st = P["step_tokens"]; L += ["## D1. The set so far at the step tokens (exact recovery, by layer)", "", "| step i | n test | " + " | ".join(f"layer {l}" for l in st["layers"]) + " |", "|---|---|" + "---|" * len(st["layers"])]
            for r in st["rows"]: L.append(f"| {r['step']} | {r['n_test']} | " + " | ".join(f"{r[f'L{l}']:.2f}" for l in st["layers"]) + " |")
            L += ["| mean over steps ≥ 4 | | " + " | ".join(f"{st['best_mean_from_4'][f'L{l}']:.2f}" for l in st["layers"]) + " |", ""]
    if C:
        c1 = C["c1"]; L += ["## C1. Swaps of the decision token's residual", "", f"1 024 same-set pairs (natural decisions differ in {c1['same_set_natural_disagree']:.3f}) and 1 024 different-set pairs of the same size (differ in {c1['diff_set_natural_disagree']:.3f}).", "", "| layer | same set: decision changed (95 % CI) | same set: to the donor's where they differ | different sets: to the donor's (95 % CI) | logit transfer |", "|---|---|---|---|---|"]
        for r in c1["layers"]: L.append(f"| {r['layer']} | {r['same_changed']:.3f} ({ci(r['same_changed_ci'])}) | {'–' if r['same_to_donor'] is None else f"{r['same_to_donor']:.3f}"} | {r['diff_to_donor']:.3f} ({ci(r['diff_to_donor_ci'])}) | {r['diff_transfer']:.2f} |")
        if "c2" in C:
            c2 = C["c2"]; L += ["", f"## C2. Membership edits along the linear set probe ({c2['n_pairs']} pairs at Hamming ≤ 2 with disjoint optimal sets and different model decisions; the best set layer {c2['best_set_layer']})", "", "| layer (probe exact there) | installed state | to the model's decision on S′ (95 % CI) | into π*(S′) | decision changed | norm / natural change | the next recorded layer's set probe reads S′ / S / the differing states as S′ |", "|---|---|---|---|---|---|---|"]
            for r in c2["layers"]:
                for k, v in r["edits"].items():
                    rt = [kk for kk in v if kk.endswith("reads_T")]; extra = f"{v[rt[0]]:.2f} / {v[rt[0].replace('reads_T', 'reads_S')]:.2f} / {v[rt[0].replace('reads_T', 'diff_states_T')]:.2f}" if rt else ""
                    L.append(f"| {r['layer']} ({r['probe_exact_here']:.2f}) | {k} | {v['to_model_T']:.3f} ({ci(v['to_model_T_ci'])}) | {v['into_opt_T']:.3f} | {v['changed']:.3f} | {v['norm_ratio']:.2f} | {extra} |")
        L.append("")
    if D:
        L += [f"## D2. The prefix patch ({D['n_pairs']} pairs; natural decisions differ in {D['natural_differ']:.3f}; the model optimal on A {D['model_optimal_A']:.3f}, on B {D['model_optimal_B']:.3f})", "", "| layer | last prefix token ← B: to B's decision (95 % CI) | into π*(B) | transfer | all prefix tokens ← B | middle prefix token ← B |", "|---|---|---|---|---|---|"]
        for r in D["layers"]: L.append(f"| {r['layer']} | {r['last_prefix_token']['to_B']:.3f} ({ci(r['last_prefix_token']['to_B_ci'])}) | {r['last_prefix_token']['into_opt_B']:.3f} | {r['last_prefix_token']['transfer']:.2f} | {r['all_prefix_tokens']['to_B']:.3f} | {r['middle_prefix_token']['to_B']:.3f} |")
        L.append("")
    # scorecard
    L += ["## Scorecard", "", "| | criterion | numbers | held |", "|---|---|---|---|"]
    if T and "llm_100000" in T["models"]:
        m = T["models"]["llm_100000"]; s = m["sufficiency"]["all"]; L.append(f"| SUF | same action on every history of a set ≥ 0.95, ≥ 0.10 above baseline | {s['same']:.3f} ({ci(s['same_ci'])}); baseline {s['baseline_same_size']:.3f} | {'yes' if s['same_ci'][0] >= 0.95 and s['same'] - s['baseline_same_size'] >= 0.10 else 'no'} |")
        tv = m["table"]; keys = list(tv); seen_n = tv[keys[0]]["n"] + tv[keys[1]]["n"]; seen_opt = (tv[keys[0]]["optimal"] * tv[keys[0]]["n"] + tv[keys[1]]["optimal"] * tv[keys[1]]["n"]) / seen_n
        L.append(f"| TABLE-IN | optimal on training-visited sets ≥ 0.95 | {seen_opt:.3f} (optimum-visited {tv[keys[0]]['optimal']:.3f}, other {tv[keys[1]]['optimal']:.3f}) | {'yes' if seen_opt >= 0.95 else 'no'} |")
        L.append(f"| TABLE-OUT | optimal on never-visited sets ≥ 0.85 | {tv[keys[2]]['optimal']:.3f} ({ci(tv[keys[2]]['optimal_ci'])}) | {'yes' if tv[keys[2]]['optimal_ci'][0] >= 0.85 else 'no'} |")
        v = m["value_shortest"]; L.append(f"| VALUE | V^π(start) ≥ 0.98 V* and mean V^π / V* ≥ 0.90 | {v['start_ratio']:.3f}; {v['mean_ratio_all']:.3f} ({ci(v['mean_ratio_ci'])}) | {'yes' if v['start_ratio'] >= 0.98 and v['mean_ratio_ci'][0] >= 0.90 else 'no'} |")
    if P:
        b = P["best_layer"]; qr = [r for r in P["layers"] if r["layer"] == b["Q_r2"]][0]["Q_r2"]; L.append(f"| READ | best Q* layer ≥ 2 above the best set layer, R² ≥ 0.90 | set {b['set_exact']}, Q* {b['Q_r2']} (R² {qr:.3f}) | {'yes' if b['Q_r2'] >= b['set_exact'] + 2 and qr >= 0.90 else 'no'} |")
        if "readout_form" in P:
            f_ = P["readout_form"]; L.append(f"| LIN | linear fit agrees with the model ≤ 0.90, MLP ≥ 0.97 | linear {f_['linear']['agreement']:.3f} ({ci(f_['linear']['agreement_ci'])}), MLP {max(f_['mlp256']['agreement'], f_['mlp1024']['agreement']):.3f} | {'yes' if f_['linear']['agreement_ci'][1] <= 0.90 and max(f_['mlp256']['agreement'], f_['mlp1024']['agreement']) >= 0.97 else 'no'} |")
    if C:
        c1 = C["c1"]["layers"]; mx = max(r["same_changed"] for r in c1); best = P["best_layer"]["set_exact"] if P else 18; hi = [r["diff_to_donor"] for r in c1 if r["layer"] >= best]
        L.append(f"| SAME | same-set swaps change ≤ 0.10 at every layer; different-set swaps ≥ 0.70 at the best set layer or above | same-set max {mx:.3f}; different-set from layer {best}: {min(hi) if hi else float('nan'):.3f}–{max(hi) if hi else float('nan'):.3f} | {'yes' if mx <= 0.10 and hi and min(hi) >= 0.70 else 'no'} |")
        if "c2" in C:
            r = [x for x in C["c2"]["layers"] if x["layer"] == C["c2"]["best_set_layer"]]
            if r:
                e = r[0]["edits"]; L.append(f"| EDIT | membership edit at the best set layer switches ≥ 0.50 to π*(S′); random and the same-subspace control ≤ 0.15 | edit {e['edit']['into_opt_T']:.3f} ({ci(e['edit']['to_model_T_ci'])} to the model's S′ decision); natural swap {e['natural_swap']['into_opt_T']:.3f}; random {e['random']['into_opt_T']:.3f}; control {e['control_same_subspace']['into_opt_T']:.3f} | {'yes' if e['edit']['into_opt_T'] >= 0.50 and e['random']['into_opt_T'] <= 0.15 and e['control_same_subspace']['into_opt_T'] <= 0.15 else 'no'} |")
    if P and "step_tokens" in P:
        st = P["step_tokens"]; bm = max(st["best_mean_from_4"].values()); L.append(f"| STEP | set so far from the step token at its best layer ≥ 0.90 (steps ≥ 4) | best layer mean {bm:.3f} | {'yes' if bm >= 0.90 else 'no'} |")
    if D and P:
        best = P["best_layer"]["set_exact"]; r = [x for x in D["layers"] if x["layer"] == best] or [min(D["layers"], key=lambda x: abs(x["layer"] - best))]
        L.append(f"| PRIOR | last prefix token patched at the best set layer switches ≥ 0.50 to B's decision | layer {r[0]['layer']}: {r[0]['last_prefix_token']['to_B']:.3f} ({ci(r[0]['last_prefix_token']['to_B_ci'])}); all prefix tokens {r[0]['all_prefix_tokens']['to_B']:.3f} | {'yes' if r[0]['last_prefix_token']['to_B_ci'][0] >= 0.50 else 'no'} |")
    Path(HERE, "tables.md").write_text("\n".join(L) + "\n"); print("\n".join(L))


if __name__ == "__main__":
    main()
